import pytest

from bedrock_protocol import v1001, v2168, v2225

# TODO: confirm against BDS: gophertunnel marshals a uint8 action and the frame rate and prefix only for Start;
# the r26_u4 dump has one uvarint32-indexed variant bound twice, so two case indices reach the wire.
# The dump wins: the action byte becomes case index 0 and a second index byte is appended.
# generated by gophertunnel b8bd735:
# &packet.PlayerVideoCapture{Action: packet.PlayerVideoCaptureActionStart, FrameRate: 60, FilePrefix: "clip"}
START = bytes.fromhex(
    "00"  # TODO: patched, confirm against BDS
    "3c00000004636c6970"
    "01"  # TODO: patched, confirm against BDS
)

PACKET = v2225.PlayerVideoCapturePacket(
    start_video_capture=v2225.PlayerVideoCapturePacket.StartVideoCapture(frame_rate=60, file_prefix="clip"),
    stop_video_capture=v2225.PlayerVideoCapturePacket.StopVideoCapture(),
)


@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_player_video_capture_is_packet_324(version):
    assert version.PACKETS[324] is version.PlayerVideoCapturePacket


def test_player_video_capture_encodes_to_its_golden():
    assert bytes(PACKET) == START


def test_player_video_capture_decodes_from_its_golden():
    assert v2225.PlayerVideoCapturePacket.from_bytes(START) == PACKET


def test_both_player_video_capture_variant_fields_reach_the_wire():
    packet = v2225.PlayerVideoCapturePacket(
        start_video_capture=v2225.PlayerVideoCapturePacket.StopVideoCapture(),
        stop_video_capture=v2225.PlayerVideoCapturePacket.StopVideoCapture(),
    )
    assert len(bytes(packet)) == 2
    assert v2225.PlayerVideoCapturePacket.from_bytes(bytes(packet)) == packet


def test_a_player_video_capture_frame_rate_above_127_keeps_its_four_fixed_bytes():
    packet = v2225.PlayerVideoCapturePacket(
        start_video_capture=v2225.PlayerVideoCapturePacket.StopVideoCapture(),
        stop_video_capture=v2225.PlayerVideoCapturePacket.StartVideoCapture(frame_rate=300, file_prefix=""),
    )
    assert len(bytes(packet)) == 7
    assert v2225.PlayerVideoCapturePacket.from_bytes(bytes(packet)) == packet
